package pe.greenminds.ecomind.community.infrastructure.persistence.jpa.adapters;
import java.util.List;import java.util.Optional;import org.springframework.stereotype.Repository;import pe.greenminds.ecomind.community.domain.model.aggregates.Event;import pe.greenminds.ecomind.community.domain.repositories.EventRepository;import pe.greenminds.ecomind.community.infrastructure.persistence.jpa.assemblers.EventPersistenceAssembler;import pe.greenminds.ecomind.community.infrastructure.persistence.jpa.repositories.EventPersistenceRepository;
@Repository public class EventRepositoryImpl implements EventRepository{private final EventPersistenceRepository repository;public EventRepositoryImpl(EventPersistenceRepository r){repository=r;}public Event save(Event e){return EventPersistenceAssembler.toDomain(repository.save(EventPersistenceAssembler.toEntity(e)));}public Optional<Event> findById(Long id){return repository.findById(id).map(EventPersistenceAssembler::toDomain);}public List<Event> findAll(Long c){return (c==null?repository.findAll():repository.findByCommunityId(c)).stream().map(EventPersistenceAssembler::toDomain).toList();}public void delete(Event e){repository.deleteById(e.getId());}}
